param([Parameter(Mandatory=$true)][string]$ExpectedManifestSha,[Parameter(Mandatory=$true)][string]$ExpectedWindowSha,[ValidateSet('Main','Conditional')][string]$Phase='Main',[string]$StageRoot='__STAGE_ROOT__')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$stage=[IO.Path]::GetFullPath($StageRoot);if($stage -ne '__STAGE_ROOT__'){throw 'Frozen flat stage required'}
$child=Join-Path $stage 'run_floorfilm_controller.ps1';$tok=$null;$errs=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($child,[ref]$tok,[ref]$errs);if(@($errs).Count){throw 'Child helper parser failure'}
foreach($d in @($ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst]},$false))){if($d.Name -notin @('Assert-Manifest','Save-Status')){. ([scriptblock]::Create($d.Extent.Text))}}
$Cores=32;$SoftGiB=112;$HardGiB=128;$FreeGiB=100;$RuntimeFreeGiB=64;$GuardSamplesRequired=2;$Mode='MeshOnly';$CaseId='NATIVE_FLAT_CONTROLS';$AttemptId='initial';$ComsolBin='__COMSOL_BIN__'
$ownedIds=@{};$ownedRootPid=$null;$ownedRootCreated=$null;$peakRss=0L;$active=$null;$manifestHash=$null;$windowHash=$null;$admissionDeadlineUtc=$null;$statusPath=Join-Path $stage 'flat_control_status.json';$root=Join-Path $stage ('flat_controls_'+$Phase.ToLowerInvariant());$points=[Collections.Generic.List[object]]::new();$started=[DateTime]::UtcNow.ToString('o')
function Assert-Manifest {$p=Join-Path $stage 'launch_manifest.json';$h=Hash $p;if($h -ne $ExpectedManifestSha.ToLowerInvariant()){throw 'Flat manifest changed'};$m=Json $p;if($m.stage_root -ne $stage -or $m.purpose -ne 'G99_P80_MATCHED_WALL_FULLWAVE_PILOT'){throw 'Wrong flat scope'};foreach($s in $m.source_hashes.PSObject.Properties){if([IO.Path]::GetFileName($s.Name) -ne $s.Name -or (Hash (Join-Path $stage $s.Name)) -ne $s.Value){throw ('Flat source changed: '+$s.Name)}};$script:manifestHash=$h}
function Save-Status([string]$State,$Resources=$null,[string]$Reason=$null){Write-Json $statusPath ([ordered]@{state=$State;phase=$Phase;started_utc=$started;updated_utc=[DateTime]::UtcNow.ToString('o');active=$active;completed=@($points.ToArray());reason=$Reason;resource=$Resources;manifest_sha256=$manifestHash;queue_window_sha256=$windowHash;peak_owned_rss_bytes=$peakRss;source_controls_only_not_cavity_qualification=$true})}
Assert-Manifest;Assert-Window;if(Test-Path $root){throw 'Flat control root exists; no implicit retry'};New-Item -ItemType Directory -Path $root -ErrorAction Stop|Out-Null
$mat=Json (Join-Path $stage 'material.json');$requests=@(@('G99_A3_P80_t3_l10p5_th0_phi0_s',10.5,0,0,'s'),@('G99_A0facets_P80_t3_l10p5_th0_phi0_s',10.5,0,0,'s'))
if($Phase -ne 'Main' -or $requests.Count -ne 2){throw 'Exactly two G99 case-bound native flat requests required'}
try{
 foreach($request in $requests){
  Assert-Manifest;Assert-Window;$approvedId=[string]$request[0];$lambda=[double]$request[1];$theta=[double]$request[2];$phi=[double]$request[3];$pol=[string]$request[4];$opt=@($mat.optical_constants|Where-Object {$_.wavelength_um -eq $lambda});if($opt.Count -ne 1){throw 'Missing flat optical material'};$id='F_'+$approvedId;$dir=Join-Path $root $id;New-Item -ItemType Directory -Path $dir -ErrorAction Stop|Out-Null
  $r=Wait-Resources;$scratch=Join-Path $dir 'scratch';New-Item -ItemType Directory -Path $scratch -ErrorAction Stop|Out-Null
  foreach($n in @('CavityFloorFilm.java','FlatObliqueAdmission.java')){Copy-Item -LiteralPath (Join-Path $stage $n) -Destination (Join-Path $dir $n) -ErrorAction Stop;if((Hash (Join-Path $stage $n)) -ne (Hash (Join-Path $dir $n))){throw 'Flat copied source SHA mismatch'}}
  $lit=$dir.Replace('\','\\');$nt=([double]$opt[0].n_ti).ToString('R',[Globalization.CultureInfo]::InvariantCulture);$kt=([double]$opt[0].k_ti).ToString('R',[Globalization.CultureInfo]::InvariantCulture)
  # COMSOL emits/loads only its entry class. Flatten all reviewed helpers into
  # that single class, exactly as the previously validated native flat runner.
  $core=[IO.File]::ReadAllText((Join-Path $dir 'CavityFloorFilm.java'),[Text.Encoding]::UTF8);$flat=[IO.File]::ReadAllText((Join-Path $dir 'FlatObliqueAdmission.java'),[Text.Encoding]::UTF8)
  $flatHeader='public class FlatObliqueAdmission {';$coreHeader='public class CavityFloorFilm {'
  if([regex]::Matches($flat,[regex]::Escape($flatHeader)).Count -ne 1 -or [regex]::Matches($core,[regex]::Escape($coreHeader)).Count -ne 1){throw 'Single-class flat merge header ambiguity'}
  $body=$flat.Substring($flat.IndexOf($flatHeader)+$flatHeader.Length).TrimEnd();if(!$body.EndsWith('}')){throw 'Flat helper class not closed'};$body=$body.Substring(0,$body.Length-1)
  foreach($pair in @(@('obj','flatObj'),@('json','flatJson'))){$body=[regex]::Replace($body,('\b'+$pair[0]+'\('),($pair[1]+'('))};$body=$body.Replace('CavityFloorFilm.','FlatEntry.')
  $entry=$core.Replace($coreHeader,'public class FlatEntry {').TrimEnd();if(!$entry.EndsWith('}')){throw 'Production core not closed'}
  $main='public static void main(String[] args) throws Exception { runPoint("'+$lit+'","'+$id+'",'+$lambda+','+$theta+','+$nt+','+$kt+',"'+$pol+'",'+$phi+'); }'
  $entry=$entry.Substring(0,$entry.Length-1)+[Environment]::NewLine+$body+[Environment]::NewLine+$main+[Environment]::NewLine+'}';[IO.File]::WriteAllText((Join-Path $dir 'FlatEntry.java'),$entry,[Text.UTF8Encoding]::new($false))
  $compiler=Join-Path $ComsolBin 'comsolcompile.exe';$batch=Join-Path $ComsolBin 'comsolbatch.exe'
  $cmd="@echo off`r`nset TEMP=$scratch`r`nset TMP=$scratch`r`ncd /d `"$dir`"`r`n"
  $cmd+="`"$compiler`" `"$dir\FlatEntry.java`" >> `"$dir\compile.stdout.log`" 2>&1`r`nif errorlevel 1 goto compile_failed`r`nif not exist `"$dir\FlatEntry.class`" goto compile_failed`r`n"
  $cmd+="findstr /C:`"Compilation failed`" `"$dir\compile.stdout.log`" > nul`r`nif not errorlevel 1 goto compile_failed`r`n> `"$dir\compile_exitcode.txt`" echo 0`r`n`"$batch`" -np 32 -tmpdir `"$scratch`" -inputfile `"$dir\FlatEntry.class`" -batchlog `"$dir\solver.log`" -autosave off > `"$dir\stdout.log`" 2>&1`r`n> `"$dir\exitcode.txt`" echo %ERRORLEVEL%`r`nexit /b`r`n:compile_failed`r`n> `"$dir\compile_exitcode.txt`" echo 2`r`n> `"$dir\exitcode.txt`" echo 2`r`nexit /b 2`r`n"
  [IO.File]::WriteAllText((Join-Path $dir 'run_flat.cmd'),$cmd,[Text.Encoding]::ASCII);$active=[pscustomobject]@{case_id=$id;directory=$dir;process_id=$null;owned_rss_bytes=0L;owned_process_ids=@();hard_samples=0;host_low_samples=0;native_progress=$null};Save-Status 'RUNNING_FLAT_SOURCE_CONTROL' $r
  $exit=Run-OwnedCmd $dir (Join-Path $dir 'run_flat.cmd');$active=$null;$compile=[int]([IO.File]::ReadAllText((Join-Path $dir 'compile_exitcode.txt')).Trim());New-Json (Join-Path $dir 'native_exit_receipt.json') ([ordered]@{case_id=$id;compile_exit_code=$compile;native_exit_code=$exit;source_core_sha256=Hash (Join-Path $stage 'CavityFloorFilm.java');source_flat_sha256=Hash (Join-Path $stage 'FlatObliqueAdmission.java');entry_sha256=Hash (Join-Path $dir 'FlatEntry.java');manifest_sha256=$manifestHash;queue_window_sha256=$windowHash})
  Assert-Manifest;Assert-Window
  if($compile -ne 0 -or $exit -ne 0){throw ('Native flat process failed: '+$id+';compile='+$compile+';exit='+$exit)};$failure=Native-Failure (Join-Path $dir 'stdout.log');if($null -ne $failure){throw (Native-FailureMessage $failure)}
  $m=Marker (Join-Path $dir 'stdout.log') 'CODEX_FLAT_ADMISSION_JSON=';if($m.case_id -ne $id -or $m.state -ne 'PASS' -or !(True $m.solver_executed) -or !(True $m.solver_completed)){throw ('Flat control not PASS: '+$id)};foreach($p in $m.checks.PSObject.Properties){if(!(True $p.Value)){throw ('Flat hard check failed: '+$id+'/'+$p.Name)}}
  Assert-EqualNumber $m 'wavelength_um' $lambda;Assert-EqualNumber $m 'theta_deg' $theta;Assert-EqualNumber $m 'phi_global_deg' $phi;if((Need $m 'polarization') -ne $pol){throw 'Actual flat polarization differs from requested'};if([Math]::Abs((Num $m 'actual_Pin_W')-1) -gt .005 -or [Math]::Abs((Num $m 'actual_R')-(Num $m 'analytic_IBC_R')) -gt .002){throw 'Independent flat power/analytic closure failed'}
  New-Json (Join-Path $dir 'metrics.json') $m;$hashes=[ordered]@{};foreach($n in @('CavityFloorFilm.java','FlatObliqueAdmission.java','FlatEntry.java','FlatEntry.class','metrics.json','native_exit_receipt.json',($id+'_model.mph'),($id+'_solved_unevaluated.mph'))){$hashes[$n]=Hash (Join-Path $dir $n)}

  Assert-Manifest;Assert-Window
  $points.Add([ordered]@{case_id=$id;approved_case_id=$approvedId;wavelength_um=$lambda;theta_deg=$theta;phi_global_deg=$phi;polarization=$pol;state='PASS';directory=$dir;metrics=$m;artifacts_sha256=$hashes;full_cavity_port_basis_admitted=$false});Save-Status 'FLAT_SOURCE_CONTROL_PASSED'
 }
 $p=Join-Path $stage $(if($Phase -eq 'Main'){'flat_control_main_admission.json'}else{'flat_control_conditional_admission.json'});$passState=if($Phase -eq 'Main'){'PASS_G99_MAIN_FLAT_SOURCE_ADMISSION'}else{'PASS_DEPTH_SCREEN_CONDITIONAL_FLAT_SOURCE_ADMISSION'};New-Json $p ([ordered]@{schema=1;state=$passState;phase=$Phase;manifest_sha256=$manifestHash;queue_window_sha256=$windowHash;source_hashes=(Json (Join-Path $stage 'launch_manifest.json')).source_hashes;points=@($points.ToArray());source_controls_only=$true;full_cavity_port_basis_requires_independent_per_case_proof=$true;frozen_source_helpers_audit_sha256=Hash (Join-Path $stage 'source_lineage_audit.json');formal_cavity_qualification=$false})
 Save-Status 'COMPLETE_NATIVE_FLAT_SOURCE_CONTROLS';[ordered]@{state=$passState;phase=$Phase;path=$p;sha256=Hash $p;native_points=$points.Count;formal_cavity_qualification=$false}|ConvertTo-Json -Depth 20
}catch{$m=$_.Exception.Message;try{Stop-OwnedIdentities}catch{$m+=';owned cleanup:'+ $_.Exception.Message};$active=$null;Save-Status 'STOPPED_FLAT_SOURCE_REVIEW_REQUIRED' $null $m;throw}
